package mz.bam.seeky.android;
import android.content.*;import android.os.Build;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
/** Supabase Auth PKCE + private, chunked, immutable cloud copies with compare-and-swap heads. */
class CloudClient {
 static final Object LOCK=new Object();final Context c;final CloudVault vault;final SharedPreferences prefs;String base,key;boolean vaultUnavailable=false;interface Progress {void update(String phase,int done,int total);}interface Cancel {boolean stopped();}
 static final class Failure extends IOException {final int status;final String code;Failure(int s,String code){super(code.equals("40001")?"Existe uma cópia mais recente noutro telemóvel. Reveja ou recupere essa versão antes de enviar.":s==401?"A sessão expirou. Entre novamente na sua conta.":s==413||s==507?"O backup excedeu o limite de ficheiro ou espaço do serviço. Os estudos locais e a última cópia concluída foram mantidos.":s==429?"O serviço recebeu demasiados pedidos. Aguarde antes de repetir o backup.":"O serviço online recusou a operação (HTTP "+s+"). Verifique a configuração e a ligação.");status=s;this.code=code;}}
 CloudClient(Context context)throws Exception{c=context.getApplicationContext();vault=new CloudVault(c);prefs=c.getSharedPreferences("cloud",0);base=prefs.getString("url","");key=prefs.getString("key","");if(base.isEmpty())try(InputStream in=c.getAssets().open("cloud.json")){JSONObject config=new JSONObject(new String(ContentText.read(in,8192),"UTF-8"));base=config.optString("url");key=config.optString("publishable_key");}}
 boolean configured(){try{CloudProtocol.base(base);validateKey(key);return true;}catch(Exception e){return false;}}
 static void validateKey(String key)throws Exception{if(key.startsWith("sb_publishable_")&&key.matches("[a-zA-Z0-9_-]{30,250}"))return;if(key.startsWith("eyJ")){String[] parts=key.split("\\.");if(parts.length==3){JSONObject payload=new JSONObject(new String(java.util.Base64.getUrlDecoder().decode(parts[1]),"UTF-8"));if(payload.optString("role").equals("anon"))return;}}throw new IllegalArgumentException("Use apenas a chave pública publishable/anon. Nunca introduza service_role, secret key ou segredos Google/Facebook no aplicativo.");}
 void configure(String url,String publicKey)throws Exception{base=CloudProtocol.base(url);key=publicKey.trim();validateKey(key);if(!prefs.edit().putString("url",base).putString("key",key).commit())throw new IOException("Não foi possível guardar a configuração.");}
 JSONObject session()throws Exception{try{JSONObject data=vault.read();vaultUnavailable=false;return data;}catch(java.security.GeneralSecurityException|org.json.JSONException e){vaultUnavailable=true;AppDiagnostics.record(c,"cloud-vault",e);prefs.edit().putString("status","Não foi possível abrir a sessão guardada. Desbloqueie o telemóvel e tente novamente. A sessão cifrada foi conservada.").apply();throw new IOException("A sessão cifrada está temporariamente indisponível; tente novamente depois de desbloquear o telemóvel.",e);}}
 boolean signedIn(){try{return !session().optString("refresh_token").isEmpty();}catch(Exception e){return false;}}
 String uid()throws Exception{return session().optJSONObject("user")==null?"":session().getJSONObject("user").getString("id");}
 String beginLogin(String provider)throws Exception{synchronized(LOCK){if(!configured())throw new IOException("O serviço de contas do Seeky ainda não foi activado. Pode continuar offline.");JSONObject settings=json("GET","/auth/v1/settings",null,false);if(settings.optJSONObject("external")==null||!settings.optJSONObject("external").optBoolean(provider,false))throw new IOException("O login com "+(provider.equals("google")?"Google":"Facebook")+" ainda não foi activado no servidor.");JSONObject state=session();String verifier=CloudProtocol.random(),nonce=CloudProtocol.random();state.put("pkce",verifier).put("state",nonce).put("login_started",System.currentTimeMillis());vault.write(state);return CloudProtocol.authorize(base,key,provider,verifier,nonce);}}
 void finishLogin(String callback)throws Exception{synchronized(LOCK){JSONObject saved=session();String code=CloudProtocol.callback(callback,saved.optString("state"),saved.optLong("login_started"),System.currentTimeMillis());JSONObject data=json("POST","/auth/v1/token?grant_type=pkce",new JSONObject().put("auth_code",code).put("code_verifier",saved.getString("pkce")),false);storeSession(data);try(StudyStore db=new StudyStore(c)){String owner=StudyState.owner(db);if(!owner.isEmpty()&&!owner.equals(uid())){vault.clear();throw new IOException("Este espaço de estudo pertence a outra conta. Use a conta anterior; não foram enviados nem misturados dados.");}}prefs.edit().putBoolean("login_seen",true).putString("status","Conta ligada. Escolha recuperar uma cópia ou activar backup.").apply();}}
 void storeSession(JSONObject data)throws Exception{String access=data.getString("access_token"),refresh=data.getString("refresh_token");if(access.isEmpty()||refresh.isEmpty())throw new IOException("Sessão inválida.");JSONObject profile=rawJson("GET","/auth/v1/user",null,access);UUID.fromString(profile.getString("id"));JSONObject saved=new JSONObject().put("access_token",access).put("refresh_token",refresh).put("expires_at",System.currentTimeMillis()+data.optLong("expires_in",3600)*1000).put("user",profile);vault.write(saved);}
 String access()throws Exception{JSONObject s=session();if(s.optString("refresh_token").isEmpty())throw new IOException("Entre na sua conta primeiro.");if(s.optLong("expires_at")<=System.currentTimeMillis()+60000){JSONObject renewed=json("POST","/auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",s.getString("refresh_token")),false);storeSession(renewed);s=session();}return s.getString("access_token");}
 void logout()throws Exception{CloudJobs.cancel(c);synchronized(LOCK){try{if(signedIn())json("POST","/auth/v1/logout?scope=local",new JSONObject(),true);}finally{vault.clear();prefs.edit().putBoolean("auto",false).putString("status","Sessão terminada; estudos mantidos neste telemóvel.").apply();CloudJobs.cancel(c);}}}
 JSONObject json(String method,String path,JSONObject data,boolean auth)throws Exception{return rawJson(method,path,data,auth?access():null);}
 JSONObject rawJson(String method,String path,JSONObject data,String token)throws Exception{byte[] b=wire(method,path,data==null?null:data.toString().getBytes("UTF-8"),"application/json",token,1048576);String value=new String(b,"UTF-8").trim();return value.isEmpty()||value.equals("null")?new JSONObject():new JSONObject(value);}
 byte[] wire(String method,String path,byte[] body,String type,String token,int max)throws Exception{if(!configured())throw new IOException("Serviço de contas ainda não activado.");URL url=new URL(CloudProtocol.base(base)+path);HttpURLConnection conn=(HttpURLConnection)url.openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(20000);conn.setReadTimeout(45000);conn.setRequestMethod(method);conn.setRequestProperty("apikey",key);conn.setRequestProperty("Accept","application/json");if(token!=null)conn.setRequestProperty("Authorization","Bearer "+token);if(body!=null){conn.setDoOutput(true);conn.setRequestProperty("Content-Type",type);conn.setRequestProperty("x-upsert","false");conn.setFixedLengthStreamingMode(body.length);}try{if(body!=null)try(OutputStream out=conn.getOutputStream()){out.write(body);}int status=conn.getResponseCode();if(status<200||status>=300){String code="";InputStream err=conn.getErrorStream();if(err!=null)try(InputStream in=err){JSONObject error=new JSONObject(new String(ContentText.read(in,16384),"UTF-8"));code=error.optString("code",error.optString("error",""));}catch(Exception ignored){}throw new Failure(status,code);}try(InputStream in=conn.getInputStream()){byte[] result=ContentText.read(in,max+1);if(result.length>max)throw new IOException("Resposta online acima do limite.");return result;}}finally{conn.disconnect();}}
 JSONArray list()throws Exception{synchronized(LOCK){byte[] response=wire("GET","/rest/v1/seeky_backups?committed=eq.true&order=revision.desc&limit=20",null,null,access(),1048576);return new JSONArray(new String(response,"UTF-8"));}}
 JSONObject head()throws Exception{byte[] response=wire("GET","/rest/v1/seeky_heads?select=revision,backup_id&limit=1",null,null,access(),16384);JSONArray data=new JSONArray(new String(response,"UTF-8"));return data.length()==0?new JSONObject().put("revision",0).put("backup_id",JSONObject.NULL):data.getJSONObject(0);}
 static String sha(byte[] bytes)throws Exception{byte[] hash=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder s=new StringBuilder();for(byte x:hash)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}
 void clearPending()throws IOException{if(!prefs.edit().remove("pending_metadata").remove("pending_id").remove("pending_uid").remove("pending_base").remove("pending_local").remove("pending_next").commit())throw new IOException("Não foi possível concluir a limpeza local do envio; o recibo foi conservado.");new File(c.getFilesDir(),"seeky-upload-pending.zip").delete();}
 void upload(Cancel cancel,Progress progress)throws Exception {
  synchronized(LOCK){try(StudyStore db=new StudyStore(c)){
   String user=uid();if(user.isEmpty())throw new IOException("Entre na sua conta primeiro.");
   JSONObject remote=head();long baseRevision=StudyState.remote(db),actual=remote.getLong("revision");
   String receipt=prefs.getString("pending_id","");
   if(!receipt.isEmpty()&&receipt.equals(remote.optString("backup_id"))&&user.equals(prefs.getString("pending_uid",""))&&actual==prefs.getLong("pending_base",-2)+1){
    long captured=prefs.getLong("pending_local",-1);StudyState.bind(db,user,actual,receipt);baseRevision=actual;
    prefs.edit().putLong("uploaded_revision",captured).putLong("last_backup",System.currentTimeMillis()).commit();clearPending();
    if(StudyState.revision(db)==captured){prefs.edit().putString("status","Backup anterior confirmado; não foi necessário reenviá-lo.").apply();return;}
   }
   if(!CloudProtocol.canPublish(StudyState.owner(db),user,baseRevision,actual))throw new Failure(409,"40001");
   File file=new File(c.getFilesDir(),"seeky-upload-pending.zip");JSONObject pending;
   String stored=prefs.getString("pending_metadata","");
   if(!stored.isEmpty()){
    pending=new JSONObject(stored);
    if(!user.equals(pending.getString("user"))||baseRevision!=pending.getLong("base"))throw new IOException("O envio pendente pertence a outro estado da conta. Reveja a cópia remota antes de continuar.");
    if(!file.isFile()||file.length()!=pending.getLong("bytes")||!StudyFiles.hash(file).equals(pending.getString("sha")))throw new IOException("O envio pendente local está incompleto. Use Descartar envio pendente; os estudos activos permanecem.");
   }else{
    if(cancel.stopped())throw new InterruptedIOException("Backup adiado.");
    progress.update("A preparar biblioteca e progresso",0,1);long before=StudyState.revision(db);
    try{try(OutputStream out=new FileOutputStream(file)){StudyBackup.write(c,db,out);}
     if(StudyState.revision(db)!=before)throw new IOException("Os estudos mudaram durante a preparação. O backup será repetido.");
     JSONArray parts=new JSONArray();try(InputStream in=new FileInputStream(file)){byte[] part;while((part=readPart(in)).length>0){if(cancel.stopped())throw new InterruptedIOException("Preparação adiada.");parts.put(new JSONObject().put("bytes",part.length).put("sha256",sha(part)));}}
     pending=new JSONObject().put("id",UUID.randomUUID().toString()).put("user",user).put("base",baseRevision).put("local",before).put("bytes",file.length()).put("sha",StudyFiles.hash(file)).put("chunks",parts);
     if(!prefs.edit().putString("pending_metadata",pending.toString()).putString("pending_id",pending.getString("id")).putString("pending_uid",user).putLong("pending_base",baseRevision).putLong("pending_local",before).putInt("pending_next",0).commit())throw new IOException("Não foi possível conservar o envio para retomar.");
    }catch(Exception e){if(prefs.getString("pending_metadata","").isEmpty())file.delete();throw e;}
   }
   String id=pending.getString("id");JSONArray chunks=pending.getJSONArray("chunks");long before=pending.getLong("local");
   if(cancel.stopped())throw new InterruptedIOException("Backup suspenso; o envio pendente será retomado.");
   String device=Build.MANUFACTURER+" "+Build.MODEL;
   json("POST","/rest/v1/rpc/seeky_begin_backup",new JSONObject().put("p_id",id).put("p_base",baseRevision).put("p_bytes",pending.getLong("bytes")).put("p_sha",pending.getString("sha")).put("p_chunks",chunks).put("p_device",device.substring(0,Math.min(120,device.length()))),true);
   int next=prefs.getInt("pending_next",0);if(next<0||next>chunks.length())throw new IOException("Estado de retoma inválido.");
   try(RandomAccessFile in=new RandomAccessFile(file,"r")){
    in.seek((long)next*CloudProtocol.CHUNK);
    for(int i=next;i<chunks.length();i++){
     if(cancel.stopped())throw new InterruptedIOException("Backup suspenso; os blocos confirmados não serão reenviados.");
     JSONObject chunk=chunks.getJSONObject(i);int bytes=chunk.getInt("bytes");if(bytes<1||bytes>CloudProtocol.CHUNK)throw new IOException("Bloco inválido.");
     byte[] part=new byte[bytes];in.readFully(part);if(!sha(part).equals(chunk.getString("sha256")))throw new IOException("Bloco local alterado; envio suspenso.");
     progress.update(next>0?"A retomar cópia privada":"A guardar cópia privada",i,chunks.length());
     String path=CloudProtocol.object(user,id,i);
     try{wire("POST","/storage/v1/object/seeky-private/"+path,part,"application/octet-stream",access(),65536);}
     catch(Failure failure){
      if(failure.status!=409&&!failure.code.equalsIgnoreCase("Duplicate")&&!failure.code.equals("409"))throw failure;
      // A response can be lost after a successful POST. Never overwrite the block.
      byte[] existing=wire("GET","/storage/v1/object/authenticated/seeky-private/"+path,null,null,access(),CloudProtocol.CHUNK);
      if(existing.length!=bytes||!sha(existing).equals(chunk.getString("sha256")))throw new IOException("Um bloco remoto existente não corresponde ao envio pendente.");
     }
     if(!prefs.edit().putInt("pending_next",i+1).commit())throw new IOException("Envio guardado no serviço; a confirmação local será reconciliada na próxima tentativa.");
    }
   }
   if(cancel.stopped())throw new InterruptedIOException("Backup suspenso antes da publicação; pode retomar.");
   JSONObject committed=json("POST","/rest/v1/rpc/seeky_commit_backup",new JSONObject().put("p_id",id).put("p_base",baseRevision),true);
   StudyState.bind(db,user,committed.getLong("revision"),id);
   if(!prefs.edit().putLong("uploaded_revision",before).putLong("last_backup",System.currentTimeMillis()).putString("status","Backup concluído e verificado para recuperação.").commit())throw new IOException("Cópia guardada no serviço; confirmação local pendente.");
   clearPending();progress.update("Backup concluído",chunks.length(),chunks.length());pruneOldCopies();
  }}
 }
 void discardPending()throws Exception{synchronized(LOCK){JSONObject remote=head();String id=prefs.getString("pending_id","");if(!id.isEmpty()&&id.equals(remote.optString("backup_id")))throw new IOException("O serviço já concluiu esta cópia. Toque em Guardar backup agora para confirmar o recibo.");String raw=prefs.getString("pending_metadata","");if(!raw.isEmpty()){JSONObject pending=new JSONObject(raw);String user=uid();if(!user.equals(pending.getString("user")))throw new IOException("O envio pertence a outra conta.");JSONArray names=new JSONArray();for(int i=0;i<pending.getJSONArray("chunks").length();i++)names.put(CloudProtocol.object(user,id,i));try{wire("DELETE","/storage/v1/object/seeky-private",new JSONObject().put("prefixes",names).toString().getBytes("UTF-8"),"application/json",access(),1048576);json("POST","/rest/v1/rpc/seeky_prune_backup",new JSONObject().put("p_id",id),true);}catch(Failure f){if(f.status!=404)throw f;}}clearPending();prefs.edit().putString("status","Envio pendente descartado. Estudos locais e cópias concluídas conservados.").apply();}}
 void restoreLocal(Progress progress)throws Exception{synchronized(LOCK){try(StudyStore db=new StudyStore(c)){File recovery=new File(c.getFilesDir(),"study-recovery-before-cloud.zip"),next=new File(c.getFilesDir(),"study-recovery-next.zip");if(!recovery.isFile())throw new IOException("Não existe uma recuperação local guardada.");long before=StudyState.revision(db);progress.update("A conservar o estado actual",0,1);try(OutputStream out=new FileOutputStream(next)){StudyBackup.write(c,db,out);}String head;try(android.database.Cursor cur=db.getReadableDatabase().rawQuery("SELECT remote_head FROM study_meta WHERE id=1",null)){cur.moveToFirst();head=cur.getString(0);}StudySnapshot.restore(c,db,recovery,before,StudyState.owner(db),StudyState.remote(db),head);java.nio.file.Files.move(next.toPath(),recovery.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);prefs.edit().putLong("last_restore",System.currentTimeMillis()).putString("status","O estado local anterior foi recuperado. A cópia online não foi alterada.").apply();}}}
 void pruneOldCopies(){try{byte[] response=wire("GET","/rest/v1/seeky_backups?order=created_at.desc&limit=100",null,null,access(),1048576);JSONArray rows=new JSONArray(new String(response,"UTF-8"));int completed=0;String user=uid();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);boolean committed=row.optBoolean("committed");if(committed&&++completed<=3)continue;if(!committed&&row.optString("id").equals(prefs.getString("pending_id","")))continue;if(!committed){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss",Locale.ROOT);f.setTimeZone(java.util.TimeZone.getTimeZone("UTC"));String raw=row.optString("created_at");if(raw.length()<19||System.currentTimeMillis()-f.parse(raw.substring(0,19)).getTime()<86400000)continue;}JSONArray parts=row.getJSONArray("chunks"),names=new JSONArray();for(int j=0;j<parts.length();j++)names.put(CloudProtocol.object(user,row.getString("id"),j));wire("DELETE","/storage/v1/object/seeky-private",new JSONObject().put("prefixes",names).toString().getBytes("UTF-8"),"application/json",access(),1048576);json("POST","/rest/v1/rpc/seeky_prune_backup",new JSONObject().put("p_id",row.getString("id")),true);}}catch(Exception e){prefs.edit().putString("retention_status","A última cópia foi guardada. Algumas cópias antigas ainda aguardam limpeza.").apply();}}
 static byte[] readPart(InputStream in)throws IOException{return CloudChunks.read(in,CloudProtocol.CHUNK);}
 File download(JSONObject backup,Cancel cancel,Progress progress)throws Exception{synchronized(LOCK){String id=backup.getString("id"),user=uid();if(!backup.getString("user_id").equals(user)||!backup.getBoolean("committed"))throw new IOException("Esta cópia não pertence à conta autenticada.");JSONArray chunks=backup.getJSONArray("chunks");if(chunks.length()<1||chunks.length()>64||backup.getLong("bytes")>CloudProtocol.MAX)throw new IOException("Cópia acima do limite.");File file=new File(c.getCacheDir(),"seeky-download-"+UUID.randomUUID()+".zip");boolean done=false;try{long total=0;try(OutputStream out=new FileOutputStream(file)){for(int i=0;i<chunks.length();i++){if(cancel.stopped())throw new InterruptedIOException("Recuperação cancelada.");progress.update("A recuperar materiais e progresso",i,chunks.length());JSONObject chunk=chunks.getJSONObject(i);byte[] part=wire("GET","/storage/v1/object/authenticated/seeky-private/"+CloudProtocol.object(user,id,i),null,null,access(),CloudProtocol.CHUNK);if(part.length!=chunk.getLong("bytes")||!sha(part).equals(chunk.getString("sha256")))throw new IOException("Um bloco da cópia não passou a verificação de integridade.");out.write(part);total+=part.length;}}if(total!=backup.getLong("bytes")||!StudyFiles.hash(file).equals(backup.getString("sha256")))throw new IOException("A integridade da cópia completa não confere.");done=true;return file;}finally{if(!done)file.delete();}}}
 void restore(JSONObject backup,Cancel cancel,Progress progress)throws Exception{synchronized(LOCK){try(StudyStore db=new StudyStore(c)){long before=StudyState.revision(db);JSONObject currentRemote=head();String owner=StudyState.owner(db),user=uid();if(!owner.isEmpty()&&!owner.equals(user))throw new IOException("O espaço local pertence a outra conta.");File download=download(backup,cancel,progress);File recovery=new File(c.getFilesDir(),"study-recovery-before-cloud.zip");try{progress.update("A conservar uma cópia local antes da recuperação",0,1);try(OutputStream out=new FileOutputStream(recovery)){StudyBackup.write(c,db,out);}if(cancel.stopped())throw new InterruptedIOException("Recuperação cancelada; estudos locais mantidos.");progress.update("A verificar e aplicar os dados",0,1);StudySnapshot.restore(c,db,download,before,user,currentRemote.getLong("revision"),currentRemote.optString("backup_id",""));prefs.edit().putLong("uploaded_revision",StudyState.revision(db)).putString("status","Estudos recuperados com materiais, anotações e posição de leitura.").putLong("last_restore",System.currentTimeMillis()).apply();}finally{download.delete();}}}}
}
